snippet_css:
:root{
  --bg: #FBFAF8;
  --fg: #3F3A4A;
  --muted: #6B5B95;
  --surface: #FFFFFF;
  --border: #E4DCF0;
  --accent: #6B5B95;
  --accent-fg: #FFFFFF;
  --radius: 24px;
  --radius-sm: 14px;
  --shadow: 0 18px 40px rgba(107,91,149,.14);
  --btn-shadow: 0 8px 24px rgba(107,91,149,.28);
  --art-bg: radial-gradient(at 22% 30%,#EBD5FF 0,transparent 42%),radial-gradient(at 78% 38%,#CDE9FF 0,transparent 42%),radial-gradient(at 50% 88%,#FFD3EA 0,transparent 42%);
  --media-bg: linear-gradient(120deg,#EBD5FF,#FFD3EA,#CDE9FF);
  --cta-bg: linear-gradient(120deg,#F3EBFF,#EAF4FF);
  --input-bg: #FFFFFF;
  --ok: #3F7A63;
  --warn: #A9556B;
  --font-display: 'Cormorant Garamond','Noto Serif TC',serif;
  --font-body: Jost,'Noto Sans TC',sans-serif;
  --font-mono: Jost,ui-sans-serif,system-ui,sans-serif;
  --focus-ring: var(--accent);
}

